        }
        let (fontFiles, fontWarnings) = validatedFonts(fontURLs)
        warnings += fontWarnings
        var assetFiles: [GraphicFile] = []
        for url in assetURLs {
            guard let bytes = try? Data(contentsOf: url) else { continue }
            // An empty `Data` crosses the FFI as NULL, which `addAsset` refuses.
            guard !bytes.isEmpty else {
                warnings.append("\(Self.relative(url)) is empty and was skipped")
                continue
            }
            assetFiles.append(GraphicFile(name: url.lastPathComponent, url: url, bytes: bytes))
        }
        var hasher = SHA256()
        for file in fontFiles + assetFiles {
            hasher.update(data: Data(file.name.utf8))
            hasher.update(data: file.bytes)
        }
        let found = GraphicScan(
            modules: modules, fonts: fontFiles, assets: assetFiles,
            libraryVersion: Self.hex(hasher.finalize()), warnings: warnings)
        return (found, true)
    }

    /// `graphics/fonts/x.ttf` for a warning.
    static func relative(_ url: URL) -> String {
        let parent = url.deletingLastPathComponent().lastPathComponent
        return "\(folderName)/\(parent)/\(url.lastPathComponent)"
    }

    /// A folder's regular files, sorted by name; empty when it is absent.
    private func listing(_ folder: URL) -> [URL] {
        let entries = (try? FileManager.default.contentsOfDirectory(
            at: folder, includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles])) ?? []
        let regular = entries.filter {
            (try? $0.resourceValues(forKeys: [.isRegularFileKey]))?.isRegularFile == true
        }
        return regular.sorted { $0.lastPathComponent < $1.lastPathComponent }
    }

    /// Arms one source; nil when it is armed, else the scan warning saying
    /// what is not watched and why (spec §11 G-20 (b)).
    private func arm(_ url: URL, folder: Bool, _ g: Int) -> String? {
        let descriptor = open(url.path, O_EVTONLY)
        guard descriptor >= 0 else {
            let code = errno
            let why = String(cString: strerror(code))
            return "\(watchSubject(url, folder: folder)) is not watched: open failed (\(why))"
        }
// app/Sources/GraphicStore+Import.swift — a font or a picture copied into
// `graphics/fonts/` or `graphics/assets/` (road map 10 §5h, G4b; G5b): the
// ONE body behind the agent's `import_graphic_font` and
// `import_graphic_asset` and a person's File ▸ Add Font to Graphics… and
// Add Image to Graphics…, so the two doors refuse in the same sentences.
//
// It goes through `ensureFolder()`, the ONE creator of `graphics/` inside a
// package (G-14), and lands the file the way `write(name:source:)` lands a
// module: a `<name>.partial` beside it, then moved into place, so the scan
// never reads half a file (a `.partial`'s extension is in neither the font
// nor the asset set, so it is never listed). `importFile` does not rescan;
// `importFont` and `importAsset` end in ONE `rescan()`, so the registry has
// its new library when they return — both are called from a handler or a
