                return Err(format!(
                    "graphic.{layer} is not an animation target; an action animates graphic.props"
                ))
            }
            other => return Err(unknown_key(&format!("graphic.{other}"), END_PATCH)),
        }
    }
    let props = match props {
        None => return Ok(read),
        Some(Value::Null) => {
    /// one key however many channels it names (GR-12), and its `qualifier`,
    /// one key however many ranges it names (GR-13); Picture counts none of
    /// them. Clip also counts an end's `speed`, the Speed section's Rate (CI-6
    /// amended by SR-21).
    func keyedCount(in end: ActionPatch, adjustment: Bool = false) -> Int {
        switch self {
        case .text: return end.text?.dictionary.count ?? 0
        case .shape: return 0
        case .graphic: return end.graphic?.props.count ?? 0
        case .picture:
            let other: Set<String> = ["motion", "color", "look", "wheels", "curves", "qualifier"]
            return end.video?.dictionary.keys.filter { !other.contains($0) }.count ?? 0
        case .color:
            return (end.video?.color?.isEmpty == false ? 1 : 0)
                + (end.video?.dictionary["look"] != nil ? 1 : 0)
                + (end.video?.wheels?.isEmpty == false ? 1 : 0)
                + (end.video?.curves?.isEmpty == false ? 1 : 0)
                + (end.video?.qualifier?.isEmpty == false ? 1 : 0)
                + (adjustment && end.video?.dictionary["opacity"] != nil ? 1 : 0)
        case .sound: return end.audio?.dictionary.count ?? 0
        case .clip:
            return (end.video?.dictionary["motion"] == nil ? 0 : 1) + (end.speed == nil ? 0 : 1)
        }
    }
}

/// The strip of sub-tabs under the action lane: equal square cells whose 1 pt
/// borders collapse into one, the active cell in the selection fill with an
/// accent border, and a mint `◆N` after a label whose tab the selected action
/// keys. Built with its tabs and its active one, like `PanelTabsView`: a pick
/// goes out through `onSelect` and the pane is rebuilt with a new strip.
    static func ordered(_ clip: ClipSnapshot) -> [ActionSnapshot] {
        clip.actions.sorted { ($0.start, $0.id) < ($1.start, $1.id) }
    }

    /// Which properties an action changes — the end patch's keys, spelled
    /// the way the model spells them, sorted (what the old Actions table
    /// printed beside each curve); `speed` when the end names a rate (spec
    /// §11 SR-21 (d)).
    static func keys(of patch: ActionPatch) -> [String] {
        var keys: [String] = []
        if let video = patch.video { keys.append(contentsOf: video.dictionary.keys) }
        if let audio = patch.audio { keys.append(contentsOf: audio.dictionary.keys) }
        if let text = patch.text { keys.append(contentsOf: text.dictionary.keys) }
        if let graphic = patch.graphic { keys.append(contentsOf: graphic.props.keys) }
        if patch.speed != nil { keys.append("speed") }
        return keys.sorted()
    }

    /// A screencast zoom's shape — `add_zoom_action` writes exactly `scale`,
    /// `x` and `y` and nothing else, so an end patch of those three keys is
    /// drawn with the zoom glyph whichever door wrote it. An end naming a rate
    /// is not a zoom (spec §11 SR-21 (d)).
    static func isZoom(_ action: ActionSnapshot) -> Bool {
        let end = action.end
        guard let video = end.video, end.audio?.isEmpty ?? true, end.text?.isEmpty ?? true,
              end.graphic?.props.isEmpty ?? true, end.speed == nil
        else { return false }
        return Set(video.dictionary.keys) == ["scale", "x", "y"]
    }

