    fn graphic_side(&self, key: &str, given: Option<u32>) -> Result<u32, String> {
        match given {
            Some(side) => {
                check_side(key, u64::from(side))?;
                Ok(side)
            }
            None => {
                let (width, height) = (self.canvas.width, self.canvas.height);
